const baseWidgetRenderer=wh;wh=function(w){if(w.type==='video')return `<div class="widget video-widget${selected===w.id?' selected':''}" data-id="${w.id}" style="left:${w.x}px;top:${w.y}px;width:${w.width||300}px;height:${w.height||450}px"><video class="chroma-video" src="${encodeURI(w.src)}" muted loop autoplay playsinline></video><canvas class="chroma-output"></canvas>${topGiftLayer(w)}${giftCounterLayer(w)}${editableGiftLayer(w)}<b>${w.title}</b>${selected===w.id?'<span class="resize-handle">↘</span>':''}</div>`;return baseWidgetRenderer(w)};
function startChroma(root=document){if(typeof view!=='undefined'&&view==='editor')return;root.querySelectorAll('.video-widget:not([data-chroma])').forEach(box=>{box.dataset.chroma='1';let v=box.querySelector('video'),c=box.querySelector('canvas'),x=c.getContext('2d',{willReadFrequently:true}),profileGift=!!box.querySelector('.profile-layer');if(profileGift){v.loop=false;v.removeAttribute('loop');v.ontimeupdate=()=>{if(!v.duration)return;box.classList.toggle('gift-details',v.currentTime>=v.duration*.35);if(v.currentTime>=v.duration*.78)box.classList.add('gift-profile')};v.onended=()=>box.classList.add('gift-details','gift-profile')}function frame(){if(v.readyState>=2){let w=Math.min(v.videoWidth||480,480),h=Math.round(w*(v.videoHeight||270)/(v.videoWidth||480));if(c.width!==w){c.width=w;c.height=h}x.drawImage(v,0,0,w,h);let im=x.getImageData(0,0,w,h),d=im.data;for(let i=0;i<d.length;i+=4){let m=Math.max(d[i],d[i+1],d[i+2]),n=Math.min(d[i],d[i+1],d[i+2]);if(m<48)d[i+3]=0;else if(m<92&&m-n<28)d[i+3]=Math.round(255*(m-48)/44)}x.putImageData(im,0,0)}requestAnimationFrame(frame)}v.play().catch(()=>{});frame()})}new MutationObserver(()=>startChroma()).observe(document.body,{childList:true,subtree:true});startChroma();
