function videoWidgetGroup(name){let raw=normalizeMediaFile(name).toLowerCase(),n=raw.replaceAll('_',' ');if(n.includes('battle/'))return'Eventeffekter';if(n.includes('leaderboard gifters')||/^(anime|classic|emerald|fire|galaxy|golden|ice|minimal|neon|retro)\.mp4$/.test(n))return'Top Gifters';if(n.includes('leaderboard likers'))return'Top Likes';if(n.includes('leaderboard points'))return'Top Points';if(n.includes('top streake'))return'Top Streak';if(n.includes('goal follows'))return'Följarmål';if(n.includes('goal likes'))return'Like-mål';if(n.includes('goal shares'))return'Delningsmål';if(n.includes('heart me goal'))return'Heart Me-mål';if(n.includes('gift campaign'))return'Gift Campaigns';if(n.includes('gift counter'))return'Gift Counter';if(n.includes('gift gallery'))return'Gift Gallery';if(n.includes('gift level')||n.includes('gem-ascend')||n.includes('cosmic-surge')||n.includes('meteor-shower'))return'Gift Level Up';if(n.includes('fan-badge')||n.includes('heart-ascend'))return'Fan Level Up';if(n.includes('like')||n.includes('heart')||n.includes('thumbs-up'))return'Like Alerts';if(n.includes('gift')||n.includes('diamond-vault')||n.includes('limousine')||n.includes('royal-crown'))return'Gift Alerts';return'Eventeffekter'}
