// Shared "Video per nivå (1-50)" editor for Fan Level Up and Gifter Level Up — a streamer can
// assign a distinct video to a specific level so e.g. level 25 plays something different from
// level 10, matching TikControl's "Single video vs Per level 1-50" pattern (see
// [[vyra_competitor_overlay_analysis]]). Levels with no assigned video keep showing the existing
// HTML/CSS template exactly as before — this is purely additive, off by default (levelVideoMode
// unset). prefix distinguishes the two widgets' DOM ids ('fan'/'gifter'); only one editor is ever
// rendered at a time (whichever widget type is selected), so the ids never collide in practice.
function levelVideoEditor(w,prefix){
  let entries=Object.entries(w.levelVideos||{}).map(([lvl,url])=>[+lvl,url]).sort((a,b)=>a[0]-b[0]);
  return `<div class="property-group level-video-editor"><h4>VIDEO PER NIVÅ (1-50)</h4><div class="switch-row one"><label><input id="${prefix}LevelVideoMode" type="checkbox" ${w.levelVideoMode?'checked':''}> Aktivera video per nivå</label></div><p class="level-video-hint">Lägg till en video för en specifik nivå — den spelas istället för standarddesignen just den nivån. Nivåer utan egen video visar standarddesignen som vanligt.</p><div class="property-grid"><label>Nivå<input id="${prefix}LevelVideoLevel" type="number" min="1" max="50" value="1"></label><label>Video-URL<input id="${prefix}LevelVideoUrl" placeholder="assets/videos/..."></label></div><button type="button" id="${prefix}AddLevelVideo">+ Lägg till video för nivå</button>${entries.length?`<div class="level-video-list">${entries.map(([lvl,url])=>`<div class="level-video-row"><span>Nivå ${lvl} · ${url.split('/').pop()}</span><button type="button" data-remove-level-video="${lvl}">×</button></div>`).join('')}</div>`:''}</div>`;
}
function bindLevelVideoEditor(w,prefix){
  let mode=document.querySelector('#'+prefix+'LevelVideoMode');
  if(mode)mode.onchange=e=>{w.levelVideoMode=e.target.checked;save();render()};
  let addBtn=document.querySelector('#'+prefix+'AddLevelVideo');
  if(addBtn)addBtn.onclick=()=>{
    let lvl=+document.querySelector('#'+prefix+'LevelVideoLevel').value,url=document.querySelector('#'+prefix+'LevelVideoUrl').value.trim();
    if(!lvl||lvl<1||lvl>50||!url){toast('Ange en nivå 1-50 och en video-URL');return}
    w.levelVideos=w.levelVideos||{};
    w.levelVideos[lvl]=url;
    save();render();
    toast('Video kopplad till nivå '+lvl);
  };
  document.querySelectorAll('[data-remove-level-video]').forEach(btn=>btn.onclick=()=>{
    delete w.levelVideos[btn.dataset.removeLevelVideo];
    save();render();
  });
}
function playLevelVideo(w,box){
  let level=w.type==='templateFanLevel'?w.fanLevel:w.gifterLevel;
  let url=w.levelVideoMode&&w.levelVideos?.[level];
  if(!url)return;
  let video=box.querySelector('.level-up-video');
  if(!video)return;
  video.src=url;
  video.currentTime=0;
  video.play().catch(()=>{});
  box.classList.add('playing-level-video');
}

