const gifterLevelBind=bind;bind=function(){gifterLevelBind();if(view!=='editor')return;let w=state.widgets.find(x=>x.id===selected);if(!w||w.type!=='templateGifterLevel')return;let set=(id,key,num=false)=>{let el=document.querySelector(id);if(el)el.onchange=e=>{w[key]=num?+e.target.value:e.target.value;save();render()}};set('#gifterHeadline','gifterHeadline');set('#gifterLabel','gifterLabel');set('#gifterLevel','gifterLevel',true);set('#gifterName','gifterName');set('#gifterMessage','gifterMessage');set('#gifterProfile','profileImage');set('#gifterColor','gifterColor');set('#gifterLight','gifterLight');set('#gifterDuration','gifterDuration',true);set('#gifterLayout','gifterLayout');bkBind(w);let layout=document.querySelector('#gifterLayout');if(layout)layout.value=w.gifterLayout||'profile';let theme=document.querySelector('#gifterTheme');if(theme){theme.value=w.gifterTheme||'royal';theme.onchange=e=>{w.gifterTheme=e.target.value;let c=gifterLevelThemes[w.gifterTheme];w.gifterColor=c[0];w.gifterLight=c[1];save();render()}}let minLevel=document.querySelector('#gifterMinLevel'),autoTrigger=document.querySelector('#gifterAutoTrigger');if(minLevel)minLevel.onchange=e=>{w.minLevel=+e.target.value;save()};if(autoTrigger)autoTrigger.onchange=e=>{w.autoTrigger=e.target.checked;save()};bindLevelVideoEditor(w,'gifter');let test=document.querySelector('#testGifterLevel');if(test)test.onclick=()=>triggerGifterLevelUp({name:w.gifterName,level:w.gifterLevel,profileImage:w.profileImage,__test:true})};
