function triggerGifterLevelUp(event={}){let widgets=state.widgets.filter(w=>w.type==='templateGifterLevel');widgets.forEach(w=>{if(event.name)w.gifterName=event.name;if(event.level)w.gifterLevel=event.level;if(event.profileImage)w.profileImage=event.profileImage});if(!widgets.length)return;save();render();widgets.forEach(w=>{if(!event.__test){if(w.autoTrigger===false)return;if((w.gifterLevel||0)<(w.minLevel||1))return}let box=document.querySelector(`[data-id="${w.id}"]`);if(!box)return;box.classList.remove('gifter-active','gifter-exit','playing-level-video');void box.offsetWidth;playLevelVideo(w,box);box.classList.add('gifter-active');clearTimeout(box._gifterTimer);clearTimeout(box._gifterExitTimer);box.style.setProperty('--gifter-exit-duration',Math.max(0,(w.gifterExitDuration||.5)*1000)+'ms');box._gifterTimer=setTimeout(()=>{const exitMs=Math.max(0,(w.gifterExitDuration||.5)*1000);box.classList.add('gifter-exit');box._gifterExitTimer=setTimeout(()=>box.classList.remove('gifter-active','gifter-exit','playing-level-video'),exitMs)},Math.max(0,(w.gifterDuration||6)*1000))});toast('Gifter Level Up triggas')}
