// OBS/TikTok-länken använder samma canvas och renderer som Studio, utan redigeringsgränssnittet.
// Widgets är positionerade i råa pixlar mot en design-yta på 432x768 — utan denna skalning skulle
// de sitta kvar i sin design-tidsstorlek oavsett vilken upplösning OBS/TikTok LIVE Studio faktiskt
// ger browser-source-fönstret, vilket är orsaken till att overlayen kunde se "större än tänkt" ut.
if(new URLSearchParams(location.search).has('overlay')){
  document.documentElement.classList.add('overlay-output');
  const onlyWidget=new URLSearchParams(location.search).get('widget');
  const fitOverlayCanvas=()=>{
    const canvas=document.querySelector('.canvas');
    if(!canvas)return;
    if(onlyWidget)canvas.querySelectorAll('.widget').forEach(widget=>widget.style.display=widget.dataset.id===onlyWidget?'':'none');
    const scale=Math.min(window.innerWidth/432,window.innerHeight/768);
    canvas.style.left=((window.innerWidth-432*scale)/2)+'px';
    canvas.style.top=((window.innerHeight-768*scale)/2)+'px';
    canvas.style.transform=`scale(${scale})`;
  };
  const overlayFitRender=render;render=function(){overlayFitRender();fitOverlayCanvas()};
  window.addEventListener('resize',fitOverlayCanvas);
  setTimeout(()=>document.querySelector('[data-view="editor"]')?.click(),0);
}

function vyraCatalogIcon(kind){let paths={gift:'<path d="M4 10h16v10H4zM12 10v10M3 7h18v3H3z"/><path d="M12 7H8.5a2.5 2.5 0 1 1 2.2-3.7L12 7Zm0 0h3.5a2.5 2.5 0 1 0-2.2-3.7L12 7Z"/>',heart:'<path d="M20.8 4.7a5.4 5.4 0 0 0-7.7 0L12 5.8l-1.1-1.1a5.4 5.4 0 0 0-7.7 7.7L12 21l8.8-8.6a5.4 5.4 0 0 0 0-7.7Z"/>',spotlight:'<path d="m12 3 1.5 4.1L18 8.5l-4.5 1.4L12 14l-1.5-4.1L6 8.5l4.5-1.4L12 3Z"/><path d="M5 14v6h14v-6M8 17h8"/>',target:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 2v3M22 12h-3M12 22v-3M2 12h3"/>',crown:'<path d="m3 7 4 4 5-7 5 7 4-4-2 11H5L3 7Z"/><path d="M5 18h14"/>',flame:'<path d="M12 22c4.4 0 7-3.1 7-7.1 0-3.3-2-6.4-5.7-9.9.1 3-1.7 4.6-3 5.4.2-2.2-.8-4-2.4-5.4.1 3.8-3 5.7-3 9.9C5 18.9 7.7 22 12 22Z"/><path d="M12 19c1.8 0 3-1.3 3-3 0-1.3-.7-2.5-2-3.7 0 1.2-.7 1.9-1.3 2.3-.1-.9-.5-1.5-1.2-2.1 0 1.5-1.5 2.3-1.5 3.5 0 1.7 1.2 3 3 3Z"/>',shield:'<path d="M12 3 20 6v5c0 5-3.4 8.4-8 10-4.6-1.6-8-5-8-10V6l8-3Z"/><path d="m9 12 2 2 4-5"/>',diamond:'<path d="m12 3 8 6-8 12L4 9l8-6Z"/><path d="m4 9 8 3 8-3M12 3v18"/>',bolt:'<path d="m13 2-8 12h7l-1 8 8-13h-7l1-7Z"/>',level:'<path d="M5 19h14M7 16l5-11 5 11M9 12h6"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[kind]||paths.diamond}</svg>`}
function applyProfessionalCatalogIcons(){document.querySelectorAll('.widget-catalog section button i').forEach(i=>{let text=i.closest('button')?.textContent.toLowerCase()||'',kind=text.includes('campaign')?'gift':text.includes('fountain')||text.includes('like goal')?'heart':text.includes('spotlight')?'spotlight':text.includes('follower goal')?'target':text.includes('fan level')||text.includes('royal')?'crown':text.includes('gifter level')?'level':text.includes('inferno')?'flame':text.includes('cyber')?'shield':text.includes('ice')?'diamond':'bolt';i.innerHTML=vyraCatalogIcon(kind);i.classList.add('vyra-pro-icon')})}
const professionalIconBind=bind;bind=function(){professionalIconBind();if(view==='editor'||view==='overlay')applyProfessionalCatalogIcons()};

function openPagedGiftPicker(w,index){document.querySelector('.gift-picker-modal')?.remove();let modal=document.createElement('div');modal.className='gift-picker-modal';modal.innerHTML=`<div><header><b>VÄLJ GIFT ${index+1}</b><button>×</button></header><input placeholder="Sök gifts (valfritt)"><section></section><footer class="gift-picker-pages"><button data-page="prev">‹ Föregående</button><strong></strong><button data-page="next">Nästa ›</button></footer></div>`;document.body.append(modal);let page=0,pageSize=30,filtered=allCampaignGiftChoices,section=modal.querySelector('section'),status=modal.querySelector('footer strong');function draw(){let pages=Math.max(1,Math.ceil(filtered.length/pageSize));page=Math.max(0,Math.min(page,pages-1));let start=page*pageSize;section.innerHTML=filtered.slice(start,start+pageSize).map(g=>`<button data-gift-file="${g.file}" data-gift-name="${g.name}"><img loading="lazy" src="${g.file}"><span>${g.name}</span></button>`).join('');status.textContent=`Sida ${page+1} av ${pages} · ${filtered.length} gifts`;modal.querySelector('[data-page="prev"]').disabled=page===0;modal.querySelector('[data-page="next"]').disabled=page>=pages-1;section.querySelectorAll('button').forEach(b=>b.onclick=()=>{w['giftImage'+index]=b.dataset.giftFile;w['giftName'+index]=b.dataset.giftName;save();modal.remove();render();toast(b.dataset.giftName+' vald')})}modal.querySelector('[data-page="prev"]').onclick=()=>{page--;draw();section.scrollTop=0};modal.querySelector('[data-page="next"]').onclick=()=>{page++;draw();section.scrollTop=0};modal.querySelector('header button').onclick=()=>modal.remove();modal.onclick=e=>{if(e.target===modal)modal.remove()};modal.querySelector('input').oninput=e=>{let q=e.target.value.trim().toLowerCase();filtered=q?allCampaignGiftChoices.filter(g=>g.name.toLowerCase().includes(q)):allCampaignGiftChoices;page=0;draw()};draw()}
const pagedGiftPickerBind=bind;bind=function(){pagedGiftPickerBind();if(view!=='editor')return;let w=state.widgets.find(x=>x.id===selected);if(!w||w.type!=='templateGiftCampaign')return;document.querySelectorAll('.open-gift-picker').forEach((button,index)=>{button.textContent='Öppna alla '+allCampaignGiftChoices.length+' gifts';button.onclick=()=>openPagedGiftPicker(w,index)})};
