const campaignPickerBind=bind;bind=function(){campaignPickerBind();if(view!=='editor')return;let w=state.widgets.find(x=>x.id===selected);if(!w||w.type!=='templateGiftCampaign')return;for(let i=0;i<4;i++){let input=document.querySelector('#giftImage'+i),group=input?.closest('.campaign-gift-editor');if(!group||group.querySelector('.open-gift-picker'))continue;let button=document.createElement('button');button.type='button';button.className='open-gift-picker';button.textContent='🎁 Välj bland '+allCampaignGiftChoices.length+' TikTok-gifts';input.closest('label').style.display='none';group.prepend(button);button.onclick=()=>{document.querySelector('.gift-picker-modal')?.remove();let modal=document.createElement('div');modal.className='gift-picker-modal';let visible=allCampaignGiftChoices.slice(0,150);modal.innerHTML='<div><header><b>VÄLJ GIFT '+(i+1)+'</b><button>×</button></header><input placeholder="Sök bland '+allCampaignGiftChoices.length+' gifts..."><section></section></div>';document.body.append(modal);let section=modal.querySelector('section'),draw=list=>section.innerHTML=list.slice(0,150).map(g=>`<button data-gift-file="${g.file}" data-gift-name="${g.name}"><img loading="lazy" src="${g.file}"><span>${g.name}</span></button>`).join('');let wire=()=>section.querySelectorAll('button').forEach(b=>b.onclick=()=>{w['giftImage'+i]=b.dataset.giftFile;w['giftName'+i]=b.dataset.giftName;save();modal.remove();render();toast(b.dataset.giftName+' vald')});draw(visible);wire();modal.querySelector('header button').onclick=()=>modal.remove();modal.onclick=e=>{if(e.target===modal)modal.remove()};modal.querySelector('input').oninput=e=>{let q=e.target.value.trim().toLowerCase(),matches=q?allCampaignGiftChoices.filter(g=>g.name.toLowerCase().includes(q)):allCampaignGiftChoices.slice(0,150);draw(matches);wire()}}}};

